CREATE TABLE IF NOT EXISTS "CRA_REPORTING_CASE" (
  "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL
, "UUID" UUID NOT NULL
, "PROJECT_ID" BIGINT NOT NULL
, "VULNERABILITY_ID" BIGINT
, "TITLE" TEXT NOT NULL
, "CASE_TYPE" TEXT NOT NULL
, "SEVERITY" TEXT
, "DESCRIPTION" TEXT
, "AWARENESS_AT" TIMESTAMPTZ(3) NOT NULL
, "EARLY_WARNING_DUE_AT" TIMESTAMPTZ(3)
, "FULL_NOTIFICATION_DUE_AT" TIMESTAMPTZ(3)
, "FINAL_REPORT_DUE_AT" TIMESTAMPTZ(3)
, "EARLY_WARNING_SUBMITTED_AT" TIMESTAMPTZ(3)
, "FULL_NOTIFICATION_SUBMITTED_AT" TIMESTAMPTZ(3)
, "FINAL_REPORT_SUBMITTED_AT" TIMESTAMPTZ(3)
, "CUSTOMERS_NOTIFIED_AT" TIMESTAMPTZ(3)
, "CSIRT" TEXT
, "STATUS" TEXT NOT NULL DEFAULT 'OPEN'
, "CREATED_AT" TIMESTAMPTZ(3) NOT NULL DEFAULT now()
, "UPDATED_AT" TIMESTAMPTZ(3) NOT NULL DEFAULT now()
, CONSTRAINT "CRA_REPORTING_CASE_PK" PRIMARY KEY ("ID")
, CONSTRAINT "CRA_REPORTING_CASE_UUID_UK" UNIQUE ("UUID")
, CONSTRAINT "CRA_REPORTING_CASE_PROJECT_FK" FOREIGN KEY ("PROJECT_ID") REFERENCES "PROJECT" ("ID") ON DELETE CASCADE
, CONSTRAINT "CRA_REPORTING_CASE_VULN_FK" FOREIGN KEY ("VULNERABILITY_ID") REFERENCES "VULNERABILITY" ("ID") ON DELETE SET NULL
, CONSTRAINT "CRA_REPORTING_CASE_TYPE_CHECK" CHECK ("CASE_TYPE" IN ('ACTIVELY_EXPLOITED_VULNERABILITY', 'SEVERE_INCIDENT'))
, CONSTRAINT "CRA_REPORTING_CASE_SEVERITY_CHECK" CHECK ("SEVERITY" IN ('CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFO', 'UNASSIGNED'))
, CONSTRAINT "CRA_REPORTING_CASE_STATUS_CHECK" CHECK ("STATUS" IN ('OPEN', 'EARLY_WARNING_SUBMITTED', 'FULL_NOTIFICATION_SUBMITTED', 'FINAL_REPORT_SUBMITTED', 'CLOSED'))
);

-- squawk-ignore require-concurrent-index-creation
CREATE INDEX IF NOT EXISTS "CRA_REPORTING_CASE_PROJECT_ID_IDX"
    ON "CRA_REPORTING_CASE" ("PROJECT_ID");

-- squawk-ignore require-concurrent-index-creation
CREATE INDEX IF NOT EXISTS "CRA_REPORTING_CASE_VULN_ID_IDX"
    ON "CRA_REPORTING_CASE" ("VULNERABILITY_ID");

-- squawk-ignore require-concurrent-index-creation
CREATE INDEX IF NOT EXISTS "CRA_REPORTING_CASE_STATUS_IDX"
    ON "CRA_REPORTING_CASE" ("STATUS");
